CREATE TABLE IF NOT EXISTS trade_order (id BIGINT NOT NULL AUTO_INCREMENT,order_no VARCHAR(40) NOT NULL,member_id BIGINT NOT NULL,total_amount DECIMAL(19,2) NOT NULL,status VARCHAR(32) NOT NULL,create_by VARCHAR(64) NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_by VARCHAR(64) NULL,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_trade_order_no(order_no),KEY idx_trade_order_member_created(member_id,create_time),KEY idx_trade_order_status_created(status,create_time),CONSTRAINT chk_trade_order_total CHECK(total_amount>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='交易订单';
CREATE TABLE IF NOT EXISTS trade_order_item (id BIGINT NOT NULL AUTO_INCREMENT,order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,product_code VARCHAR(64) NOT NULL,product_name VARCHAR(200) NOT NULL,unit_price DECIMAL(19,2) NOT NULL,quantity INT NOT NULL,line_amount DECIMAL(19,2) NOT NULL,create_by VARCHAR(64) NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_by VARCHAR(64) NULL,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_trade_order_item_order(order_id),CONSTRAINT fk_trade_order_item_order FOREIGN KEY(order_id) REFERENCES trade_order(id),CONSTRAINT chk_trade_order_item_quantity CHECK(quantity>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='交易订单明细';